import React, { Component } from "react";
import "./Homepage.css";
import PagesJson from "./PagesJson";

export default class Homepage extends Component {
    constructor(props) {
        super(props);
        this.state = {
            currentImageIndex: 0
        };
    }

    nextImage = () => {
        this.setState(prevState => ({
            currentImageIndex: (prevState.currentImageIndex + 1) % this.state.gallery.length
        }));
    }

    prevImage = () => {
        this.setState(prevState => ({
            currentImageIndex: (prevState.currentImageIndex - 1 + this.state.gallery.length) % this.state.gallery.length
        }));
    }

    render() {
        const homeData = PagesJson.find(item => item.pageId === 5);
        const contentHome = homeData.content;
        const gallery = homeData.gallery;
        const squares = homeData.squares;

        return (
            <div className="containersq">
                <div className="gallery-container">
                    <div className="arrow-container">
                        <button className="arrow" onClick={this.prevImage}>&#10094;</button>
                        <img src={gallery[this.state.currentImageIndex]} className="gallery-image" alt="Gallery" />
                        <button className="arrow" onClick={this.nextImage}>&#10095;</button>
                    </div>
                </div>

                <div className="sentence1">
                    {contentHome.map((item, index) => (
                        <p key={index}>{item.t1}</p>
                    ))}
                </div>
                <div className="sentence2">
                    {contentHome.map((item, index) => (
                        <p key={index}>{item.t2}</p>
                    ))}
                </div>
                <a className="findmypet" href="/Service">Find my pet</a>
                <div className="squares-container">
                    {squares.map((square, index) => (
                        <div key={index} className="square">{square.text}</div>
                    ))}
                </div>
            </div>
        );
    }
}
